const app=document.querySelector('#app');
const state={session:null,sessions:null,notifications:null,me:null,admin:null,catalog:null,view:'home',adminTab:'overview',keyFilter:'all',keyQuery:'',selectedKey:null,keyTraffic:null};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>(v/100).toLocaleString('ru-RU',{style:'currency',currency:'RUB'});
const bytes=v=>{for(const u of ['Б','КБ','МБ','ГБ','ТБ']){if(v<1024)return `${v.toFixed(v<10?1:0)} ${u}`;v/=1024}return `${v.toFixed(1)} ПБ`};
const date=v=>v?new Date(v*1000).toLocaleDateString('ru-RU'):'бессрочно';
const request=async(url,options={})=>{const r=await fetch(url,{credentials:'same-origin',cache:url.startsWith('/api/')?'no-store':'default',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});if(!r.ok)throw new Error(await r.text()||r.status);return r.status===204?null:r.json()};
const toast=text=>{const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)};
const nav=[['home','⌂','Обзор'],['shop','＋','Купить'],['keys','⌁','Мои ключи'],['finance','₽','Финансы'],['notifications','●','Уведомления'],['support','?','Поддержка']];
const brand=()=>state.catalog?.brand||'ZuevVPN';
app.addEventListener('click',async event=>{if(event.target.id!=='enableBrowserNotifications')return;event.stopImmediatePropagation();if(!('Notification'in window)||!('serviceWorker'in navigator)){toast('Браузер не поддерживает PWA-уведомления');return}const permission=await Notification.requestPermission();if(permission!=='granted'){toast('Разрешение не предоставлено');return}try{const registration=await navigator.serviceWorker.ready;await registration.showNotification(brand(),{body:'Уведомления веб-кабинета включены',icon:'/assets/icon.svg',badge:'/assets/icon.svg',tag:'awgram-enabled'});if('periodicSync'in registration)await registration.periodicSync.register('awgram-notifications',{minInterval:15*60*1000}).catch(()=>{});toast('PWA-уведомления включены')}catch(e){toast('Не удалось включить уведомления')}} ,true);
app.addEventListener('click',async event=>{const detail=event.target.closest?.('.key-detail');if(detail){const key=state.me.keys.find(item=>item.name===detail.dataset.key);if(!key)return;state.selectedKey=key;state.keyTraffic=null;render();state.keyTraffic=await request(`/api/keys/${encodeURIComponent(key.name)}/traffic?days=7`).catch(()=>({points:[],totals:{rx:0,tx:0,online_minutes:0}}));render();return}if(event.target.id==='closeKeyDetail'||event.target.id==='closeKeyButton'){state.selectedKey=null;state.keyTraffic=null;render()}});
app.addEventListener('input',event=>{if(event.target.id!=='crmSearch')return;const q=event.target.value.toLowerCase();document.querySelectorAll('#crmUsers .crm-row').forEach(row=>row.hidden=!row.dataset.search.includes(q))});
app.addEventListener('click',async event=>{const user=event.target.closest?.('.crm-user-action'),ticket=event.target.closest?.('.crm-ticket-action');if(!user&&!ticket)return;const item=user||ticket;if(!confirm('Подтвердить административное действие?'))return;try{await request(`/api/admin/${user?'users':'tickets'}/${item.dataset.id}/action`,{method:'POST',body:JSON.stringify({action:item.dataset.action})});state.admin=await request('/api/admin/overview');toast('Изменение сохранено');render()}catch(e){toast(e.message)}});
app.addEventListener('click',async event=>{if(event.target.id==='promoActivate'){const code=document.querySelector('#promoCode').value.trim();try{const out=await request('/api/promos/activate',{method:'POST',body:JSON.stringify({code})});state.me.discount_percent=out.discount_percent;document.querySelector('#promoResult').innerHTML=`<div class="success">Скидка ${out.discount_percent}% активирована для следующей покупки.</div>`}catch(e){toast(e.message)}return}if(event.target.id==='copyReferral'){const value=document.querySelector('#referralLink').value;await navigator.clipboard.writeText(value).catch(()=>{});toast('Ссылка скопирована')}});
app.addEventListener('click',async event=>{const create=event.target.closest?.('#createTransfer'),action=event.target.closest?.('.transfer-action');if(!create&&!action)return;try{if(create){const recipient=document.querySelector('#transferRecipient').value.trim();if(!recipient)throw new Error('Укажите внутренний ID, Telegram ID или username');await request(`/api/keys/${encodeURIComponent(create.dataset.key)}/transfer`,{method:'POST',body:JSON.stringify({recipient})});state.selectedKey=null}else{if(action.dataset.action==='accept'&&!confirm('После подтверждения прежний владелец потеряет доступ к ключу. Продолжить?'))return;await request(`/api/transfers/${action.dataset.id}/action`,{method:'POST',body:JSON.stringify({action:action.dataset.action})})}state.me=await request('/api/me');toast('Передача обновлена');render()}catch(e){toast(e.message)}});
app.addEventListener('click',async event=>{if(event.target.id!=='legacySubmit')return;const name=document.querySelector('#legacyName').value.trim(),comment=document.querySelector('#legacyComment').value.trim(),code=document.querySelector('#legacyCode').value.trim();try{const out=await request('/api/legacy/requests',{method:'POST',body:JSON.stringify({name,comment:comment||null,code:code||null})});document.querySelector('#legacyResult').innerHTML=`<div class="success">Заявка #${out.request_id} отправлена администратору. Можно создать следующую.</div>`;document.querySelector('#legacyName').value='';document.querySelector('#legacyComment').value=''}catch(e){toast(e.message)}});
new MutationObserver(()=>{const input=document.querySelector('#transferRecipient');if(input){input.type='text';input.placeholder='Внутренний ID, Telegram ID или @username'}const box=document.querySelector('.transfer-box');if(box&&!document.querySelector('#keyFolder')){box.insertAdjacentHTML('beforebegin',`<div class="folder-box"><label for="keyFolder">Папка ключа</label><div class="inline-form"><input id="keyFolder" maxlength="40" value="${esc(state.selectedKey?.folder||'')}" placeholder="Например, Семья"><button class="button" id="saveFolder">Сохранить</button></div></div>`)}}).observe(app,{childList:true,subtree:true});
new MutationObserver(()=>{if(state.view==='support')document.querySelectorAll('.split .card:nth-child(2) .list-row').forEach((row,i)=>{if(state.me.tickets[i]){row.dataset.ticketOpen=state.me.tickets[i].id;row.classList.add('ticket-row')}});document.querySelectorAll('.crm-ticket-action').forEach(button=>{const row=button.closest('.crm-row');if(row&&!row.querySelector('[data-ticket-open]'))row.querySelector('.actions')?.insertAdjacentHTML('afterbegin',`<button class="button" data-ticket-open="${button.dataset.id}">Открыть</button>`)})}).observe(app,{childList:true,subtree:true});
app.addEventListener('click',async event=>{if(event.target.id==='saveFolder'){const folder=document.querySelector('#keyFolder').value.trim();await request(`/api/keys/${encodeURIComponent(state.selectedKey.name)}/folder`,{method:'PATCH',body:JSON.stringify({folder:folder||null})});state.selectedKey.folder=folder||null;const key=state.me.keys.find(k=>k.name===state.selectedKey.name);if(key)key.folder=folder||null;toast('Папка сохранена')}if(event.target.closest?.('[data-view="notifications"]')){state.notifications=await request('/api/notifications/feed').catch(()=>({items:[]}));render()}});
app.addEventListener('click',async event=>{if(event.target.id==='readNotifications'){await request('/api/notifications/read',{method:'POST'});state.notifications=await request('/api/notifications/feed');render()}if(event.target.id==='enableBrowserNotifications'){if(!('Notification'in window)){toast('Браузер не поддерживает уведомления');return}const permission=await Notification.requestPermission();if(permission==='granted'){new Notification(brand(),{body:'Уведомления веб-кабинета включены',icon:'/assets/icon.svg'});toast('Уведомления включены')}else toast('Разрешение не предоставлено')}});
function closeSupportDialog(dialog=document.querySelector('.support-dialog-backdrop')){dialog?.remove();document.body.classList.toggle('modal-open',Boolean(document.querySelector('.modal-backdrop')))}
app.addEventListener('click',async event=>{const open=event.target.closest?.('[data-ticket-open]');if(open){try{const d=await request(`/api/support/${open.dataset.ticketOpen}`);closeSupportDialog();document.body.insertAdjacentHTML('beforeend',supportDialog(d));document.body.classList.add('modal-open');const body=document.querySelector('.support-dialog-body');body?.scrollTo(0,body.scrollHeight)}catch(e){toast(e.message)}return}const close=event.target.closest?.('[data-close-support]');if(close){closeSupportDialog(close.closest('.modal-backdrop'));return}if(event.target.classList?.contains('support-dialog-backdrop')){closeSupportDialog(event.target);return}const closeTicket=event.target.closest?.('#closeSupportTicket');if(closeTicket){if(!confirm('Закрыть обращение? Пользователь увидит его как завершённое.'))return;try{await request(`/api/admin/tickets/${closeTicket.dataset.id}/action`,{method:'POST',body:JSON.stringify({action:'close'})});closeSupportDialog();state.admin=await request('/api/admin/overview');state.me=await request('/api/me');toast('Обращение закрыто');render()}catch(e){toast(e.message)}return}if(event.target.id==='supportReply'){try{const id=event.target.dataset.id,message=document.querySelector('#supportReplyText').value.trim();if(!message)throw new Error('Введите текст ответа');await request(`/api/support/${id}`,{method:'POST',body:JSON.stringify({message})});closeSupportDialog();toast('Ответ отправлен');state.me=await request('/api/me');if(state.session.is_admin)state.admin=await request('/api/admin/overview');render()}catch(e){toast(e.message)}}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeSupportDialog()});
app.addEventListener('click',async event=>{const payment=event.target.closest?.('.crm-payment-action'),balance=event.target.closest?.('.crm-balance');if(payment){let reason=null;if(payment.dataset.action==='reject'){reason=prompt('Причина отказа');if(!reason)return}if(!confirm('Подтвердить действие с платежом?'))return;try{await request(`/api/admin/payments/${payment.dataset.id}/action`,{method:'POST',body:JSON.stringify({action:payment.dataset.action,reason})});state.admin=await request('/api/admin/overview');state.me=await request('/api/me');toast('Платёж обработан');render()}catch(e){toast(e.message)}return}if(balance){const amount=Number(prompt('Сумма в рублях. Для списания укажите минус:'));if(!amount)return;const reason=prompt('Причина корректировки:');if(!reason)return;try{await request(`/api/admin/users/${balance.dataset.id}/balance`,{method:'POST',body:JSON.stringify({amount_rubles:amount,reason})});state.admin=await request('/api/admin/overview');toast('Баланс изменён');render()}catch(e){toast(e.message)}}});
app.addEventListener('click',async event=>{const profile=event.target.closest?.('.crm-profile');if(profile){try{const d=await request(`/api/admin/users/${profile.dataset.id}`);document.body.insertAdjacentHTML('beforeend',adminProfileDialog(d))}catch(e){toast(e.message)}return}if(event.target.id==='closeAdminProfile')event.target.closest('.modal-backdrop').remove()});
app.addEventListener('click',async event=>{const renew=event.target.closest?.('.renew-key');if(!renew)return;const key=state.me.keys.find(k=>k.name===renew.dataset.key);let months=12;if(!key?.legacy){months=Number(prompt('На сколько месяцев продлить: 1, 3, 6 или 12?',12));if(![1,3,6,12].includes(months))return}try{const out=await request(`/api/keys/${encodeURIComponent(renew.dataset.key)}/renew`,{method:'POST',body:JSON.stringify({months})});toast(`Заявка #${out.payment_id} создана на ${money(out.amount_kopecks)}`);state.me=await request('/api/me');render()}catch(e){toast(e.message)}});
app.addEventListener('click',async event=>{if(event.target.id==='adminPromoCreate'){const code=document.querySelector('#adminPromoCode').value,discount_percent=Number(document.querySelector('#adminPromoDiscount').value),max_uses=Number(document.querySelector('#adminPromoLimit').value)||null;try{await request('/api/admin/promos',{method:'POST',body:JSON.stringify({code,discount_percent,max_uses,expires_at:null})});state.admin=await request('/api/admin/overview');toast('Промокод создан');render()}catch(e){toast(e.message)}return}const action=event.target.closest?.('.admin-promo-action');if(action){try{await request(`/api/admin/promos/${encodeURIComponent(action.dataset.code)}/action`,{method:'POST',body:JSON.stringify({action:action.dataset.action})});state.admin=await request('/api/admin/overview');render()}catch(e){toast(e.message)}}});
app.addEventListener('click',async event=>{if(event.target.id==='partnerTransfer'){const amount_rubles=Number(document.querySelector('#partnerAmount').value);try{await request('/api/partner/wallet/transfer',{method:'POST',body:JSON.stringify({amount_rubles,requisites:null})});state.me=await request('/api/me');toast('Средства переведены на основной баланс');render()}catch(e){toast(e.message)}return}if(event.target.id==='partnerWithdraw'){const amount_rubles=Number(document.querySelector('#partnerAmount').value),requisites=document.querySelector('#partnerRequisites').value;try{const out=await request('/api/partner/wallet/withdraw',{method:'POST',body:JSON.stringify({amount_rubles,requisites})});state.me=await request('/api/me');toast(`Заявка #${out.withdrawal_id} отправлена`);render()}catch(e){toast(e.message)}}});
app.addEventListener('click',async event=>{const action=event.target.closest?.('.withdrawal-action');if(!action)return;let reason=null;if(action.dataset.action==='reject'){reason=prompt('Причина отказа');if(!reason)return}if(!confirm('Подтвердить решение по выводу?'))return;try{await request(`/api/admin/withdrawals/${action.dataset.id}/action`,{method:'POST',body:JSON.stringify({action:action.dataset.action,reason})});state.admin=await request('/api/admin/overview');toast('Заявка обработана');render()}catch(e){toast(e.message)}});

new MutationObserver(()=>{document.querySelectorAll('#crmUsers .crm-row').forEach(row=>{const action=row.querySelector('.crm-user-action');if(action&&!row.querySelector('.crm-balance'))action.insertAdjacentHTML('beforebegin',`<button class="button crm-profile" data-id="${action.dataset.id}">Профиль</button><button class="button crm-balance" data-id="${action.dataset.id}">Баланс</button>`)})}).observe(app,{childList:true,subtree:true});

new MutationObserver(()=>{if(state.view!=='admin'||!state.admin||document.querySelector('#adminPromos'))return;const root=document.querySelector('.content');if(!root)return;const rows=(state.admin.promos||[]).map(p=>`<div class="list-row"><div><strong>${esc(p.code)}</strong><div class="muted">${p.discount_percent}% · использовано ${p.used_count}${p.max_uses===null?'':' из '+p.max_uses}</div></div><button class="button admin-promo-action" data-code="${esc(p.code)}" data-action="${p.active?'disable':'enable'}">${p.active?'Отключить':'Включить'}</button></div>`).join('');root.insertAdjacentHTML('beforeend',`<section class="card" id="adminPromos" style="margin-top:18px"><h2>Промокоды</h2><div class="inline-form"><input id="adminPromoCode" maxlength="32" placeholder="Код"><input id="adminPromoDiscount" type="number" min="1" max="100" placeholder="Скидка %"><input id="adminPromoLimit" type="number" min="1" placeholder="Лимит (необязательно)"><button class="button primary" id="adminPromoCreate">Создать</button></div>${rows||'<p class="muted">Промокодов пока нет.</p>'}</section>`) }).observe(app,{childList:true,subtree:true});

new MutationObserver(()=>{const w=state.me?.partner_wallet;if(state.view!=='finance'||!w||document.querySelector('#partnerWallet'))return;const root=document.querySelector('.content');if(!root)return;const withdrawals=(w.withdrawals||[]).map(x=>`<div class="list-row"><span>Вывод #${x.id} · ${esc(x.status)}</span><strong>${money(x.amount_kopecks)}</strong></div>`).join('');root.insertAdjacentHTML('beforeend',`<section class="card" id="partnerWallet" style="margin-top:18px"><div class="section-head"><div><div class="eyebrow">Партнёрский баланс</div><h2>${money(w.available_kopecks)} доступно</h2><p class="muted">В удержании: ${money(w.hold_kopecks)}</p></div></div><div class="inline-form"><input id="partnerAmount" type="number" min="1" placeholder="Сумма, ₽"><button class="button" id="partnerTransfer">На основной баланс</button></div><div class="inline-form" style="margin-top:10px"><input id="partnerRequisites" maxlength="300" placeholder="Реквизиты для вывода"><button class="button primary" id="partnerWithdraw">Вывести от 1000 ₽</button></div>${withdrawals?`<h3>Заявки на вывод</h3>${withdrawals}`:''}</section>`) }).observe(app,{childList:true,subtree:true});

new MutationObserver(()=>{if(state.view!=='admin'||!state.admin||document.querySelector('#adminWithdrawals'))return;const items=state.admin.partner_withdrawals||[];if(!items.length)return;const rows=items.map(x=>`<div class="list-row"><div><strong>Заявка #${x.id} · ${money(x.amount_kopecks)}</strong><div class="muted">Партнёр #${x.partner_id} · ${esc(x.requisites)}</div></div><div class="actions"><button class="button primary withdrawal-action" data-id="${x.id}" data-action="paid">Выплачено</button><button class="button danger withdrawal-action" data-id="${x.id}" data-action="reject">Отказать</button></div></div>`).join('');document.querySelector('.content')?.insertAdjacentHTML('beforeend',`<section class="card" id="adminWithdrawals" style="margin-top:18px"><h2>Партнёрские выплаты</h2>${rows}</section>`) }).observe(app,{childList:true,subtree:true});

new MutationObserver(()=>{if(state.view!=='keys')return;const container=document.querySelector('.content>section.keys');if(!container||container.dataset.grouped||container.querySelector('.empty'))return;const now=Date.now()/1000,q=state.keyQuery.toLowerCase(),items=state.me.keys.filter(k=>{const online=k.last_handshake&&now-k.last_handshake<300,problem=k.server_status!=='online'||k.enabled===false||(k.expires_at&&k.expires_at<=now),unused=!k.last_handshake,ok=state.keyFilter==='online'?online:state.keyFilter==='unused'?unused:state.keyFilter==='problem'?problem:true;return ok&&`${k.device} ${k.name} ${k.location}`.toLowerCase().includes(q)});const cards=[...container.children],groups=new Map();items.forEach((key,i)=>{const folder=key.folder||'Без папки';if(!groups.has(folder))groups.set(folder,[]);if(cards[i])groups.get(folder).push(cards[i])});container.textContent='';groups.forEach((nodes,folder)=>{const section=document.createElement('section');section.className='key-folder';section.innerHTML=`<div class="folder-heading"><h2>${esc(folder)}</h2><span class="badge">${nodes.length}</span></div><div class="keys"></div>`;nodes.forEach(node=>section.lastElementChild.appendChild(node));container.appendChild(section)});container.dataset.grouped='1'}).observe(app,{childList:true,subtree:true});

function shell(content,title='Личный кабинет'){
 const items=[...nav,...(state.session.is_admin?[['admin','◈','Админка']]:[])];
 return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="logo">◈</span>${esc(brand())}</div><article class="account-card"><div class="avatar">${esc((state.me.display_name||'U')[0]).toUpperCase()}</div><div><strong>${esc(state.me.display_name||'Пользователь')}</strong><small>Личный кабинет</small></div></article><article class="side-balance"><small>Баланс</small><strong>${money(state.me.balance_kopecks)}</strong></article><nav class="nav">${items.map(([id,icon,label])=>`<button data-view="${id}" class="${state.view===id?'active':''} ${id==='admin'?'admin-only':''}"><span>${icon}</span><span>${label}</span></button>`).join('')}</nav><div class="sidebar-foot"><button class="button ghost" id="logout">Выйти</button></div></aside><main class="content"><header class="topbar"><div><div class="eyebrow">Личный кабинет</div><h1>${title}</h1></div><div class="top-actions"><span class="system-ok">● Все системы работают</span><button class="theme-toggle" id="themeToggle" title="Сменить тему">◐</button><div class="avatar">${esc((state.me.display_name||'U')[0]).toUpperCase()}</div></div></header>${content}</main></div>`;
}
function keyCard(k){const now=Date.now()/1000,expired=k.expires_at&&k.expires_at<=now,blocked=['blocked','archived'].includes(k.server_status),down=k.server_status!=='online',disabled=k.enabled===false,online=k.last_handshake&&now-k.last_handshake<300,everUsed=Boolean(k.last_handshake||k.rx||k.tx);const label=expired?'Срок истёк':blocked?'Требуется замена':down?'Сервер недоступен':disabled?'Отключён':online?'Сейчас онлайн':everUsed?'Готов к работе':'Ещё не использовался',legacyNote=k.legacy?(everUsed?'Legacy · учитывается в декабрьском продлении':'Legacy · ни разу не использовался, оплата не требуется'):'';return `<article class="card key ${blocked?'key-problem':''}"><div><span class="badge ${expired||down||disabled?'bad':online?'':'warn'}">${label}</span><h3>${esc(k.device)}</h3><div class="muted">#${k.id} · ${esc(k.name)} · ${esc(k.location)} · ${k.protocol==='amneziawg-2'?'AWG 2.0':'AWG 1.0'}</div>${legacyNote?`<div class="legacy-note ${everUsed?'':'free'}">${legacyNote}</div>`:''}<div class="actions"><button class="button primary key-detail" data-key="${esc(k.name)}">Подробнее</button><a class="button" href="/api/keys/${encodeURIComponent(k.name)}/config">Скачать</a><a class="button" target="_blank" href="/api/keys/${encodeURIComponent(k.name)}/qr">QR-код</a>${!k.legacy||everUsed?`<button class="button renew-key" data-key="${esc(k.name)}">Продлить</button>`:''}<button class="button rename-key" data-key="${esc(k.name)}" data-label="${esc(k.device)}">Переименовать</button></div></div><div><div class="muted">Создан</div><strong>${date(k.created_at)}</strong><div class="muted">Подключение: ${online?'сейчас':k.last_handshake?date(k.last_handshake):'ещё не было'}</div><div class="muted">Срок: ${date(k.expires_at)}</div></div><div><div class="muted">Трафик всего</div><strong>↓ ${bytes(k.rx)}</strong><div>↑ ${bytes(k.tx)}</div></div></article>`}
function keyDetail(){const k=state.selectedKey,t=state.keyTraffic;if(!k)return'';const points=t?.points||[],values=points.map(p=>p.rx+p.tx),max=Math.max(1,...values),poly=values.map((v,i)=>`${points.length<2?0:i/(points.length-1)*100},${46-v/max*42}`).join(' ');return `<div class="modal-backdrop" id="closeKeyDetail"><article class="modal card" onclick="event.stopPropagation()"><div class="section-head"><div><div class="eyebrow">Подключение</div><h2>${esc(k.device)}</h2></div><button class="theme-toggle" id="closeKeyButton">×</button></div><div class="muted">${esc(k.name)} · ${esc(k.location)}</div><section class="grid key-detail-metrics"><article class="metric"><span class="muted">Получено за 7 дней</span><strong>${bytes(t?.totals?.rx||0)}</strong></article><article class="metric"><span class="muted">Отправлено</span><strong>${bytes(t?.totals?.tx||0)}</strong></article><article class="metric"><span class="muted">Активность</span><strong>${Math.round((t?.totals?.online_minutes||0)/60)} ч</strong></article></section><div class="traffic-chart">${points.length?`<svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="График трафика"><polyline points="${poly}"/></svg>`:'<div class="empty muted">История появится после сбора телеметрии.</div>'}</div><details class="transfer-box"><summary>Передать ключ другому пользователю</summary><p class="muted">Укажите Telegram ID получателя. Ключ останется вашим до его подтверждения.</p><div class="inline-form"><input id="transferRecipient" type="number" placeholder="Telegram ID"><button class="button" id="createTransfer" data-key="${esc(k.name)}">Предложить передачу</button></div></details><div class="actions"><a class="button primary" href="/api/keys/${encodeURIComponent(k.name)}/config">Скачать конфигурацию</a><a class="button" target="_blank" href="/api/keys/${encodeURIComponent(k.name)}/qr">Открыть QR-код</a></div></article></div>`}
function home(){const d=state.me,now=Date.now()/1000,active=d.keys.filter(k=>!k.expires_at||k.expires_at>now),online=d.keys.filter(k=>k.last_handshake&&now-k.last_handshake<300),expiring=d.keys.filter(k=>k.expires_at&&k.expires_at>now&&k.expires_at-now<604800);return shell(`${expiring.length?`<article class="notice"><div><strong>Скоро потребуется продление</strong><p>${expiring.length} ${expiring.length===1?'подключение заканчивается':'подключения заканчиваются'} в ближайшие 7 дней.</p></div><button class="button primary" data-view="finance">Перейти к оплате</button></article>`:''}<section class="hero"><article class="card"><div class="eyebrow">Всё под контролем</div><h2>Здравствуйте, ${esc(d.display_name||'пользователь')}</h2><p class="muted">Подключения, оплата, трафик и помощь собраны в одном кабинете.</p><div class="actions"><button class="button primary" data-view="shop">＋ Новое подключение</button><button class="button" data-view="restore">♻ Восстановить ключи</button><button class="button" data-view="keys">Мои ключи</button></div></article><article class="card"><div class="muted">Баланс аккаунта</div><div class="balance">${money(d.balance_kopecks)}</div><button class="button" data-view="finance">＋ Пополнить</button><div class="muted">Активных подключений: ${active.length}</div></article></section><section class="grid metrics"><article class="metric"><span class="muted">Активные</span><strong>${active.length}</strong></article><article class="metric"><span class="muted">Сейчас онлайн</span><strong>${online.length}</strong></article><article class="metric"><span class="muted">Нужно продлить</span><strong>${expiring.length}</strong></article><article class="metric"><span class="muted">Приглашено</span><strong>${d.referral_count}</strong><button class="text-button" data-view="finance">Пригласить друга →</button></article></section><div class="section-head"><h2>Последние подключения</h2><button class="text-button" data-view="keys">Показать все →</button></div><section class="keys">${d.keys.slice(0,3).map(keyCard).join('')||'<article class="card empty">Пока нет ключей</article>'}</section>`,'Обзор')}
function restore(){return shell(`<section class="grid split"><article class="card"><div class="eyebrow">Legacy-восстановление</div><h2>Вернуть ранее выданный ключ</h2><p class="muted">Можно подать несколько заявок. Каждую проверяет администратор перед созданием ключа.</p><input id="legacyName" maxlength="64" placeholder="Желаемое имя ключа"><textarea id="legacyComment" maxlength="500" placeholder="Комментарий или устройство (необязательно)"></textarea><input id="legacyCode" maxlength="64" placeholder="Промокод, если ещё не активирован"><button class="button primary wide" id="legacySubmit">Отправить заявку</button><div id="legacyResult"></div></article><article class="card"><h2>Как это работает</h2><div class="list-row"><span>1</span><span>Укажите имя старого ключа</span></div><div class="list-row"><span>2</span><span>При первом обращении введите OLDKEY</span></div><div class="list-row"><span>3</span><span>Администратор проверит и восстановит подключение</span></div><p class="muted">Заявки принимаются до установленной даты программы восстановления.</p></article></section>`,'Восстановление ключей')}
function notificationCenter(){const items=state.notifications?.items||[];return shell(`<div class="section-head"><p class="muted">События ключей, оплат, обращений и серверов</p><div class="actions"><button class="button" id="enableBrowserNotifications">Включить уведомления PWA</button><button class="button" id="readNotifications">Прочитать все</button></div></div><section class="stack notification-list">${items.map(n=>`<article class="card notification ${n.read?'':'unread'}"><div><span class="badge">${esc(n.kind)}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small class="muted">${new Date(n.created_at*1000).toLocaleString('ru-RU')}</small></div>${n.action_url?`<a class="button" href="${esc(n.action_url)}">Открыть</a>`:''}</article>`).join('')||'<article class="card empty"><h2>Уведомлений пока нет</h2><p class="muted">Здесь появятся важные события вашего аккаунта.</p></article>'}</section>`,'Уведомления')}
function supportDialog(d){const closed=d.ticket.status==='closed',admin=Boolean(state.session?.is_admin);return `<div class="modal-backdrop support-dialog-backdrop" role="presentation"><article class="modal card support-dialog" role="dialog" aria-modal="true" aria-labelledby="supportDialogTitle"><header class="support-dialog-head"><div><div class="eyebrow">Обращение #${d.ticket.id}</div><h2 id="supportDialogTitle">${esc(d.ticket.subject)}</h2></div><button class="theme-toggle support-dialog-close" data-close-support aria-label="Закрыть окно">×</button></header><div class="support-dialog-body"><div class="support-messages">${d.messages.map(m=>`<div class="support-message ${m.is_admin?'admin':'user'}"><strong>${m.is_admin?'Поддержка':'Пользователь'}</strong><p>${esc(m.text||'Вложение')}</p><small>${date(m.created_at)}</small></div>`).join('')||'<p class="muted">Сообщений пока нет.</p>'}</div>${closed?'<div class="support-closed">Обращение закрыто</div>':`<label class="auth-label" for="supportReplyText">Ваш ответ</label><textarea id="supportReplyText" maxlength="2000" placeholder="Введите сообщение поддержке"></textarea>`}</div><footer class="support-dialog-actions">${!closed?`<button class="button primary" id="supportReply" data-id="${d.ticket.id}">Отправить ответ</button>`:''}${admin&&!closed?`<button class="button danger" id="closeSupportTicket" data-id="${d.ticket.id}">Закрыть обращение</button>`:''}<button class="button" data-close-support>Закрыть окно</button></footer></article></div>`}
function adminProfileDialog(d){return `<div class="modal-backdrop"><article class="modal card"><div class="section-head"><div><div class="eyebrow">Профиль #${d.user.id}</div><h2>${esc(d.user.display_name)}</h2><p class="muted">${d.user.username?'@'+esc(d.user.username):'без username'} · с ${date(d.user.created_at)}</p></div><button class="theme-toggle" id="closeAdminProfile">×</button></div><section class="grid key-detail-metrics"><article class="metric"><span class="muted">Баланс</span><strong>${money(d.user.balance_kopecks)}</strong></article><article class="metric"><span class="muted">Ключи</span><strong>${d.keys.length}</strong></article><article class="metric"><span class="muted">Приглашено</span><strong>${d.user.referral_count}</strong></article></section><h3>Подключения</h3><div class="stack">${d.keys.map(k=>`<div class="list-row"><div><strong>${esc(k.device)}</strong><div class="muted">${esc(k.name)} · ${esc(k.location)} · ${esc(k.server_status)}</div></div><div>↓ ${bytes(k.rx)} · ↑ ${bytes(k.tx)}</div></div>`).join('')||'<p class="muted">Нет ключей.</p>'}</div><h3>Последние платежи</h3>${d.payments.slice(0,8).map(p=>`<div class="list-row"><span>#${p.id} · ${esc(p.status)}</span><strong>${money(p.amount_kopecks)}</strong></div>`).join('')||'<p class="muted">Нет платежей.</p>'}</article></div>`}
const dashboardHome=home;home=()=>state.view==='restore'?restore():state.view==='notifications'?notificationCenter():dashboardHome();
function keys(){const now=Date.now()/1000,q=state.keyQuery.toLowerCase(),filtered=state.me.keys.filter(k=>{const online=k.last_handshake&&now-k.last_handshake<300,problem=k.server_status!=='online'||k.enabled===false||(k.expires_at&&k.expires_at<=now),unused=!k.last_handshake;const filter=state.keyFilter==='online'?online:state.keyFilter==='unused'?unused:state.keyFilter==='problem'?problem:true;return filter&&`${k.device} ${k.name} ${k.location}`.toLowerCase().includes(q)}),transfers=(state.me.transfers||[]).map(t=>`<div class="list-row"><div><strong>${esc(t.client_name)}</strong><div class="muted">${t.incoming?`От ${esc(t.from_name)}`:`Для ${esc(t.to_name)}`} · действует 24 часа</div></div><div class="actions">${t.incoming?`<button class="button primary transfer-action" data-id="${t.id}" data-action="accept">Принять</button>`:''}<button class="button transfer-action" data-id="${t.id}" data-action="cancel">Отменить</button></div></div>`).join('');return shell(`${transfers?`<article class="card transfer-notice"><h2>Ожидающие передачи</h2>${transfers}</article>`:''}<section class="key-tools"><input id="keySearch" value="${esc(state.keyQuery)}" placeholder="Поиск по названию, ключу или локации"><div class="filters">${[['all','Все'],['online','Онлайн'],['unused','Не использовались'],['problem','Требуют внимания']].map(([id,label])=>`<button class="filter ${state.keyFilter===id?'active':''}" data-filter="${id}">${label}</button>`).join('')}</div></section><section class="keys">${filtered.map(keyCard).join('')||'<article class="card empty"><h2>Ничего не найдено</h2><p class="muted">Измените фильтр или поисковый запрос.</p></article>'}</section>${keyDetail()}`,'Мои подключения')}
function shop(){const c=state.catalog,discount=state.me.discount_percent||0;return shell(`<section class="hero"><article class="card"><div class="eyebrow">Новое подключение</div><h2>Купить ключ AWG 1.0</h2><p class="muted">Выберите локацию и срок. Заявка появится одновременно в веб-кабинете и Telegram-боте.</p>${discount?`<span class="badge">Ваша скидка ${discount}%</span>`:''}</article><article class="card"><div class="muted">Ваш баланс</div><div class="balance">${money(state.me.balance_kopecks)}</div></article></section><section class="grid split"><article class="card"><h2>1. Локация</h2><div class="choice-grid">${c.servers.map((s,i)=>`<label class="choice"><input type="radio" name="server" value="${s.id}" ${i===0?'checked':''}><span><strong>${esc(s.location)}</strong><small>${esc(s.protocol)} · свободно ${s.available}</small></span></label>`).join('')||'<p class="muted">Сейчас нет серверов для новых подключений.</p>'}</div></article><article class="card"><h2>2. Срок</h2><div class="choice-grid">${c.tariffs.map((t,i)=>{const price=t.price_kopecks*(100-discount)/100;return `<label class="choice"><input type="radio" name="term" value="${t.months}" ${i===0?'checked':''}><span><strong>${t.months} мес.</strong><small>${discount?`<s>${money(t.price_kopecks)}</s> `:''}${money(price)}</small></span></label>`}).join('')}</div><button class="button primary wide" id="purchase" ${c.servers.length?'':'disabled'}>Оформить заказ</button><div id="purchaseResult"></div></article></section>`,'Купить VPN')}
function finance(){const d=state.me,p=d.payments.map(x=>`<div class="list-row"><div><strong>Заявка #${x.id}</strong><div class="muted">${esc(x.method)} · ${date(x.created_at)}</div></div><strong>${money(x.amount_kopecks)} · ${esc(x.status)}</strong></div>`).join(''),h=d.balance_history.map(x=>`<div class="list-row"><div>${esc(x.kind)}</div><strong>${x.amount_kopecks>0?'+':''}${money(x.amount_kopecks)}</strong></div>`).join(''),bot=state.catalog?.bot_username?.replace(/^@/,''),ref=bot?`https://t.me/${bot}?start=ref_${d.user_id}`:'';return shell(`<section class="grid split"><article class="card"><h2>Пополнить баланс</h2><p class="muted">Создайте заявку и укажите номер банковской операции.</p><input id="amount" type="number" min="100" max="100000" placeholder="Сумма от 100 ₽"><button class="button primary" id="topup">Создать заявку</button><div id="proofBox"></div></article><article class="card"><h2>Промокод</h2><p class="muted">Скидка применяется к одной следующей покупке.</p><div class="inline-form"><input id="promoCode" maxlength="64" placeholder="Введите промокод"><button class="button" id="promoActivate">Применить</button></div><div id="promoResult"></div></article><article class="card"><h2>Пригласить друга</h2><div class="balance">${d.referral_percent}%</div><p class="muted">начисляется на баланс после подтверждённой покупки приглашённого. Уже приглашено: ${d.referral_count}.</p>${ref?`<div class="copy-field"><input id="referralLink" readonly value="${esc(ref)}"><button class="button" id="copyReferral">Копировать</button></div>`:'<p class="muted">Подключите публичного бота-зеркало, чтобы получить ссылку.</p>'}</article><article class="card"><h2>История баланса</h2>${h||'<p class="muted">Операций пока нет.</p>'}</article></section><article class="card" style="margin-top:18px"><h2>Платежи</h2>${p||'<p class="muted">Заявок пока нет.</p>'}</article>`,'Финансы')}
function support(){const tickets=state.me.tickets.map(t=>`<div class="list-row"><div><strong>Обращение #${t.id}</strong><div class="muted">${esc(t.category)}</div></div><span class="badge">${esc(t.status)}</span></div>`).join('');const email=state.session.email?`<span class="badge">Подтверждена</span><h3>${esc(state.session.email)}</h3><p class="muted">Этот адрес можно использовать для резервного входа без Telegram.</p>`:state.session.email_login_enabled?`<p class="muted">Подтвердите почту — она станет независимым способом входа, если Telegram недоступен.</p><input id="bindEmail" type="email" autocomplete="email" placeholder="you@example.ru"><button class="button primary" id="bindEmailSend">Получить код</button><div id="bindConfirm"></div>`:'<p class="muted">Администратор пока не настроил почтовый шлюз.</p>';const sessions=state.sessions?.sessions?.map(s=>`<div class="list-row"><div><strong>${s.current?'Текущая сессия':'Вход в кабинет'}</strong><div class="muted">Создана ${date(s.created_at)} · до ${date(s.expires_at)}</div></div>${s.current?'<span class="badge">сейчас</span>':''}</div>`).join('')||'<p class="muted">Загружаем активные входы…</p>';return shell(`<section class="grid split"><article class="card"><h2>Написать в поддержку</h2><textarea id="supportText" maxlength="1000" placeholder="Опишите вопрос или проблему"></textarea><button class="button primary" id="supportSend">Отправить</button></article><article class="card"><h2>Мои обращения</h2>${tickets||'<p class="muted">Обращений пока нет.</p>'}</article><article class="card"><h2>Резервный вход по почте</h2>${email}</article><article class="card"><h2>Активные входы</h2>${sessions}<button class="button danger wide" id="revokeSessions">Завершить остальные сессии</button></article></section>`,'Поддержка')}
function adminCrm(d){const users=(d.crm_users||[]).map(u=>`<div class="crm-row" data-search="${esc(`${u.display_name} ${u.username||''} ${u.email||''} ${u.user_id}`.toLowerCase())}"><div><strong>${esc(u.display_name)}</strong><small>${u.username?'@'+esc(u.username):esc(u.email||'без контакта')} · ID ${u.user_id}</small></div><span>${u.keys} ключ. · ${money(u.balance_kopecks)}</span><button class="button ${u.blocked?'':'danger'} crm-user-action" data-id="${u.user_id}" data-action="${u.blocked?'unblock':'block'}">${u.blocked?'Разблокировать':'Заблокировать'}</button></div>`).join('');const payments=(d.crm_payments||[]).map(p=>`<div class="list-row"><div><strong>#${p.id} · ID ${p.user_id}</strong><div class="muted">${esc(p.method)} · ${date(p.created_at)}${p.proof?' · подтверждение приложено':''}</div></div><strong>${money(p.amount_kopecks)}</strong></div>`).join('');const tickets=(d.crm_tickets||[]).map(t=>`<div class="crm-row"><div><strong>#${t.id} · ${esc(t.subject)}</strong><small>ID ${t.user_id} · ${esc(t.category)} · ${esc(t.priority)}</small></div><span class="badge">${esc(t.status)}</span><div class="actions"><button class="button crm-ticket-action" data-id="${t.id}" data-action="take">Взять</button><button class="button crm-ticket-action" data-id="${t.id}" data-action="close">Закрыть</button></div></div>`).join('');return `<section class="card crm" style="margin-top:18px"><div class="section-head"><div><h2>Пользователи</h2><p class="muted">Последние 250 активных аккаунтов</p></div><input id="crmSearch" placeholder="Имя, username, почта или ID"></div><div id="crmUsers" class="crm-list">${users||'<p class="muted">Пользователей нет.</p>'}</div></section><section class="grid split" style="margin-top:18px"><article class="card"><h2>Ожидающие платежи</h2>${payments||'<p class="muted">Нет заявок.</p>'}</article><article class="card"><h2>Обращения</h2>${tickets||'<p class="muted">Нет открытых обращений.</p>'}</article></section>`}
function admin(){if(!state.admin)return shell('<article class="card empty"><div class="loader"></div></article>','Админ-панель');const d=state.admin;return shell(`<section class="grid metrics"><article class="metric"><span class="muted">Пользователи</span><strong>${d.users.total}</strong><small class="muted">+${d.users.new_today} сегодня</small></article><article class="metric"><span class="muted">Ключи</span><strong>${d.keys.total}</strong><small class="muted">${d.keys.online} онлайн</small></article><article class="metric"><span class="muted">Выручка</span><strong>${money(d.revenue_kopecks)}</strong><small class="muted">подтверждено</small></article><article class="metric"><span class="muted">Ожидают оплаты</span><strong>${d.payments_pending}</strong><small class="muted">поддержка: ${d.support_open}</small></article></section><section class="card"><div class="admin-title"><div><h2>Серверы и миграция</h2><p class="muted">Вывод узла, снимок кампании и архив доступны без Telegram. Опасные действия требуют подтверждения.</p></div><label class="compact">Очистка через <select id="cleanupDays">${[7,14,30,60,90].map(x=>`<option ${d.cleanup.days===x?'selected':''}>${x}</option>`).join('')}</select> дней</label></div><div class="server-admin-list">${d.servers.map(s=>`<article class="server-admin ${s.archived?'archived':''}"><div class="server-admin-head"><div><strong>${esc(s.name)}</strong><div class="muted">${esc(s.location)} · ${esc(s.protocol)} · ${s.clients}/${s.capacity}</div></div><span class="badge ${s.operator_unavailable||s.archived||s.status!=='online'?'bad':''}">${s.archived?'архив':s.operator_unavailable?'нерабочий':esc(s.status)}</span></div><div class="progress"><span style="width:${Math.min(100,s.capacity?s.clients/s.capacity*100:0)}%"></span></div><div class="muted server-meta">Онлайн: ${s.online} · трафик ↓ ${bytes(s.rx)} ↑ ${bytes(s.tx)}${s.unavailable_reason?` · причина: ${esc(s.unavailable_reason)}`:''}</div><div class="actions"><button class="button server-action" data-id="${s.id}" data-action="snapshot">Снимок миграции</button>${s.archived?`<button class="button server-action" data-id="${s.id}" data-action="restore">Вернуть</button>`:s.operator_unavailable?`<button class="button server-action" data-id="${s.id}" data-action="available">Снять отметку</button><button class="button danger server-action" data-id="${s.id}" data-action="archive">В архив</button>`:`<button class="button danger server-action" data-id="${s.id}" data-action="unavailable">Пометить нерабочим</button>`}<button class="button server-action" data-id="${s.id}" data-action="${s.provisioning?'provision_off':'provision_on'}">Выдача: ${s.provisioning?'вкл':'выкл'}</button></div></article>`).join('')}</div></section><section class="card" style="margin-top:18px"><h2>Аудитория</h2><div class="list-row"><span>Новые за 30 дней</span><strong>${d.users.new_30d}</strong></div><div class="list-row"><span>Платящие</span><strong>${d.users.paying}</strong></div><div class="list-row"><span>Заблокированы</span><strong>${d.users.blocked}</strong></div></section>${adminCrm(d)}`,'Админ-панель')}
function customerHomeV2(){const d=state.me,now=Date.now()/1000,active=d.keys.filter(k=>!k.expires_at||k.expires_at>now),online=d.keys.filter(k=>k.last_handshake&&now-k.last_handshake<300),problem=d.keys.filter(k=>k.server_status!=='online'||k.enabled===false||(k.expires_at&&k.expires_at<=now)),expiring=d.keys.filter(k=>k.expires_at&&k.expires_at>now&&k.expires_at-now<604800),traffic=d.keys.reduce((sum,k)=>sum+k.rx+k.tx,0),healthy=Math.max(0,active.length-problem.length),ordered=[...d.keys].sort((a,b)=>Number(problem.includes(b))-Number(problem.includes(a)));const health=problem.length?'Требуется внимание':active.length?'VPN готов к работе':'Нет подключений';return shell(`${problem.length?`<article class="notice danger-notice"><div><strong>Нужно проверить подключения: ${problem.length}</strong><p>Есть заблокированные, отключённые или просроченные ключи.</p></div><button class="button primary" data-open-key-filter="problem">Показать</button></article>`:expiring.length?`<article class="notice"><div><strong>Скоро потребуется продление</strong><p>${expiring.length} подключений заканчиваются в ближайшие 7 дней.</p></div><button class="button primary" data-view="finance">Продлить</button></article>`:''}<section class="client-overview"><article class="card welcome-card"><div><div class="eyebrow">Личный кабинет</div><h2>${esc(d.display_name||'Пользователь')}, всё необходимое рядом</h2><p class="muted">Создавайте подключения, следите за сроком и получайте помощь без поиска по меню.</p></div><div class="quick-actions"><button class="quick-action primary" data-view="shop"><span>＋</span><strong>Новое подключение</strong><small>Выбрать сервер и срок</small></button><button class="quick-action" data-view="keys"><span>⌁</span><strong>Мои ключи</strong><small>${d.keys.length} подключений</small></button><button class="quick-action" data-view="restore"><span>♻</span><strong>Восстановление</strong><small>Вернуть старый ключ</small></button><button class="quick-action" data-view="support"><span>?</span><strong>Помощь</strong><small>Написать поддержке</small></button></div></article><article class="card health-card ${problem.length?'has-problem':''}"><div class="health-orb"><strong>${healthy}</strong><small>исправно</small></div><div><span class="badge ${problem.length?'bad':''}">${health}</span><h2>${online.length} сейчас онлайн</h2><p class="muted">Всего трафика: ${bytes(traffic)}</p></div></article></section><section class="grid metrics client-metrics"><article class="metric"><span class="muted">Активные</span><strong>${active.length}</strong><small class="muted">из ${d.keys.length} ключей</small></article><article class="metric"><span class="muted">Онлайн</span><strong>${online.length}</strong><small class="muted">за последние 5 минут</small></article><article class="metric"><span class="muted">Баланс</span><strong>${money(d.balance_kopecks)}</strong><button class="text-button" data-view="finance">Пополнить →</button></article><article class="metric"><span class="muted">Приглашено</span><strong>${d.referral_count}</strong><button class="text-button" data-view="finance">Пригласить →</button></article></section><div class="section-head"><div><h2>Ваши подключения</h2><p class="muted">Проблемные показываются первыми</p></div><button class="text-button" data-view="keys">Все подключения →</button></div><section class="keys">${ordered.slice(0,3).map(keyCard).join('')||'<article class="card empty"><h2>Создайте первое подключение</h2><p class="muted">Выберите сервер и срок — конфигурация появится здесь.</p><button class="button primary" data-view="shop">Выбрать VPN</button></article>'}</section>`,'Обзор')}
function adminTabs(){return `<nav class="admin-tabs" aria-label="Разделы админки">${[['overview','Обзор'],['infrastructure','Серверы'],['customers','Пользователи'],['operations','Заявки']].map(([id,label])=>`<button class="${state.adminTab===id?'active':''}" data-admin-tab="${id}">${label}</button>`).join('')}</nav>`}
function adminServerList(d){return `<section class="card"><div class="admin-title"><div><h2>Серверы и выдача</h2><p class="muted">Состояние, загрузка, миграция и доступность для новых ключей.</p></div><label class="compact">Очистка через <select id="cleanupDays">${[7,14,30,60,90].map(x=>`<option ${d.cleanup.days===x?'selected':''}>${x}</option>`).join('')}</select> дней</label></div><div class="server-admin-list">${d.servers.map(s=>`<article class="server-admin ${s.archived?'archived':''}"><div class="server-admin-head"><div><strong>${esc(s.name)}</strong><div class="muted">${esc(s.location)} · ${esc(s.protocol)} · ${s.clients}/${s.capacity}</div></div><span class="badge ${s.operator_unavailable||s.archived||s.status!=='online'?'bad':''}">${s.archived?'архив':s.operator_unavailable?'нерабочий':esc(s.status)}</span></div><div class="progress"><span style="width:${Math.min(100,s.capacity?s.clients/s.capacity*100:0)}%"></span></div><div class="muted server-meta">Онлайн: ${s.online} · ↓ ${bytes(s.rx)} · ↑ ${bytes(s.tx)}${s.unavailable_reason?` · ${esc(s.unavailable_reason)}`:''}</div><div class="actions"><button class="button server-action" data-id="${s.id}" data-action="snapshot">Снимок</button>${s.archived?`<button class="button server-action" data-id="${s.id}" data-action="restore">Вернуть</button>`:s.operator_unavailable?`<button class="button server-action" data-id="${s.id}" data-action="available">Снять отметку</button><button class="button danger server-action" data-id="${s.id}" data-action="archive">В архив</button>`:`<button class="button danger server-action" data-id="${s.id}" data-action="unavailable">Пометить нерабочим</button>`}<button class="button server-action" data-id="${s.id}" data-action="${s.provisioning?'provision_off':'provision_on'}">Выдача: ${s.provisioning?'вкл':'выкл'}</button></div></article>`).join('')||'<p class="muted">Серверы не добавлены.</p>'}</div></section>`}
function adminUsersV2(d){const users=(d.crm_users||[]).map(u=>`<div class="crm-row" data-search="${esc(`${u.display_name} ${u.username||''} ${u.email||''} ${u.user_id}`.toLowerCase())}"><div><strong>${esc(u.display_name)}</strong><small>${u.username?'@'+esc(u.username):esc(u.email||'без контакта')} · ID ${u.user_id}</small></div><span>${u.keys} ключ. · ${money(u.balance_kopecks)}</span><div class="actions"><button class="button crm-profile" data-id="${u.user_id}">Профиль</button><button class="button crm-balance" data-id="${u.user_id}">Баланс</button><button class="button ${u.blocked?'':'danger'} crm-user-action" data-id="${u.user_id}" data-action="${u.blocked?'unblock':'block'}">${u.blocked?'Разблокировать':'Блокировать'}</button></div></div>`).join('');return `<section class="card crm"><div class="section-head admin-search-head"><div><h2>Пользователи</h2><p class="muted">Поиск по имени, username, почте или ID</p></div><input id="crmSearch" placeholder="Найти пользователя"></div><div id="crmUsers" class="crm-list">${users||'<p class="muted">Пользователей нет.</p>'}</div></section>`}
function legacyBilling(d){const rows=(d.legacy_billing||[]).map(u=>`<details class="legacy-billing-row"><summary><span><strong>${esc(u.display_name)}</strong><small>${u.username?'@'+esc(u.username):'ID '+u.user_id} · восстановлено ${u.keys.length}</small></span><span><strong>${money(u.total_kopecks)}</strong><small>к оплате: ${u.billable} · без оплаты: ${u.unused}</small></span></summary><div class="legacy-key-list">${u.keys.map(k=>`<div class="list-row"><span>${esc(k.name)}<small>${k.last_handshake?'последнее подключение '+date(k.last_handshake):'подключений не было'}</small></span><span class="badge ${k.used?'':'warn'}">${k.used?'учитывается':'не оплачивается'}</span></div>`).join('')}</div><p class="muted">Цена: ${money(u.unit_price_kopecks)} за используемый ключ/год · ${u.discount_enabled?'индивидуальная скидка включена':'стандартная цена без скидки'}. Для одного перевода пользователь может пополнить внутренний баланс на ${money(u.total_kopecks)}, после чего продлить используемые ключи.</p><div class="actions"><button class="button ${u.discount_enabled?'danger':'primary'} crm-user-action" data-id="${u.user_id}" data-action="${u.discount_enabled?'legacy_discount_disable':'legacy_discount_enable'}">${u.discount_enabled?'Отключить скидку':'Включить скидку'}</button></div></details>`).join('');return `<article class="card legacy-billing"><div class="section-head"><div><h2>Legacy: восстановление и оплата</h2><p class="muted">По умолчанию для всех действует фиксированная цена 1000 ₽ за используемый ключ в год. Льготную шкалу 750/500 ₽ можно включить индивидуально.</p></div><span class="badge">${(d.legacy_billing||[]).reduce((n,u)=>n+u.billable,0)} платных</span></div>${rows||'<p class="muted">Восстановленных legacy-ключей пока нет.</p>'}</article>`}
function adminOperationsV2(d){const payments=(d.crm_payments||[]).map(p=>`<div class="operation-row"><div><span class="badge warn">${p.method==='legacy_manual'?'legacy-продление':'оплата'}</span><strong>Заявка #${p.id}${p.client_name?' · '+esc(p.client_name):''}</strong><small>ID ${p.user_id} · ${esc(p.method)} · ${date(p.created_at)}${p.proof?' · подтверждение есть':''}</small></div><strong>${money(p.amount_kopecks)}</strong><div class="actions"><button class="button primary crm-payment-action" data-id="${p.id}" data-action="approve">Принять</button><button class="button danger crm-payment-action" data-id="${p.id}" data-action="reject">Отклонить</button></div></div>`).join(''),tickets=(d.crm_tickets||[]).map(t=>`<div class="operation-row"><div><span class="badge">поддержка</span><strong>#${t.id} · ${esc(t.subject)}</strong><small>ID ${t.user_id} · ${esc(t.category)} · ${esc(t.priority)}</small></div><span class="badge">${esc(t.status)}</span><div class="actions"><button class="button" data-ticket-open="${t.id}">Открыть</button><button class="button crm-ticket-action" data-id="${t.id}" data-action="take">Взять</button><button class="button crm-ticket-action" data-id="${t.id}" data-action="close">Закрыть</button></div></div>`).join('');return `<section class="admin-columns"><article class="card"><div class="section-head"><div><h2>Ожидающие платежи</h2><p class="muted">${(d.crm_payments||[]).length} требуют решения</p></div></div><div class="operation-list">${payments||'<p class="muted">Нет заявок на оплату.</p>'}</div></article><article class="card"><div class="section-head"><div><h2>Обращения</h2><p class="muted">${(d.crm_tickets||[]).length} в работе</p></div></div><div class="operation-list">${tickets||'<p class="muted">Нет открытых обращений.</p>'}</div></article></section>${legacyBilling(d)}`}
function adminOverviewV2(d){const badServers=d.servers.filter(s=>s.archived||s.operator_unavailable||s.status!=='online'),tasks=d.payments_pending+d.support_open+badServers.length;return `<section class="admin-hero"><article class="card"><div class="eyebrow">Центр управления</div><h2>${tasks?`${tasks} задач требуют внимания`:'Система работает штатно'}</h2><p class="muted">Платежи, обращения и инфраструктура собраны по приоритету.</p><div class="actions"><button class="button primary" data-admin-tab="operations">Открыть заявки</button><button class="button" data-admin-tab="infrastructure">Проверить серверы</button></div></article><article class="card admin-health ${tasks?'warn':''}"><strong>${badServers.length?'Есть проблемы':'Стабильно'}</strong><span class="muted">${d.servers.filter(s=>s.status==='online'&&!s.archived).length}/${d.servers.filter(s=>!s.archived).length} серверов онлайн</span></article></section><section class="grid metrics"><article class="metric"><span class="muted">Пользователи</span><strong>${d.users.total}</strong><small class="muted">+${d.users.new_today} сегодня</small></article><article class="metric"><span class="muted">Ключи</span><strong>${d.keys.total}</strong><small class="muted">${d.keys.online} онлайн</small></article><article class="metric"><span class="muted">Выручка</span><strong>${money(d.revenue_kopecks)}</strong><small class="muted">подтверждено</small></article><article class="metric"><span class="muted">Очередь</span><strong>${tasks}</strong><small class="muted">нужно обработать</small></article></section><section class="admin-priorities"><button class="card priority-card" data-admin-tab="operations"><span class="priority-icon">₽</span><div><strong>${d.payments_pending} платежей</strong><small>ожидают подтверждения</small></div><span>→</span></button><button class="card priority-card" data-admin-tab="operations"><span class="priority-icon">?</span><div><strong>${d.support_open} обращений</strong><small>нужен ответ поддержки</small></div><span>→</span></button><button class="card priority-card" data-admin-tab="infrastructure"><span class="priority-icon">◈</span><div><strong>${badServers.length} серверов</strong><small>требуют внимания</small></div><span>→</span></button></section><section class="grid split"><article class="card"><h2>Аудитория</h2><div class="list-row"><span>Новые за 30 дней</span><strong>${d.users.new_30d}</strong></div><div class="list-row"><span>Платящие</span><strong>${d.users.paying}</strong></div><div class="list-row"><span>Заблокированы</span><strong>${d.users.blocked}</strong></div></article><article class="card"><h2>Инфраструктура</h2>${d.servers.slice(0,4).map(s=>`<div class="list-row"><span>${esc(s.name)}</span><span class="badge ${s.status!=='online'||s.archived?'bad':''}">${s.archived?'архив':esc(s.status)}</span></div>`).join('')}</article></section>`}
function adminV2(){if(!state.admin)return shell('<article class="card empty"><div class="loader"></div></article>','Админ-панель');const d=state.admin,content=state.adminTab==='infrastructure'?adminServerList(d):state.adminTab==='customers'?adminUsersV2(d):state.adminTab==='operations'?adminOperationsV2(d):adminOverviewV2(d);return shell(`${adminTabs()}${content}`,'Админ-панель')}
home=()=>state.view==='restore'?restore():state.view==='notifications'?notificationCenter():customerHomeV2();
admin=adminV2;
app.addEventListener('click',event=>{const tab=event.target.closest?.('[data-admin-tab]');if(tab){state.adminTab=tab.dataset.adminTab;app.dataset.adminTabPage=state.adminTab;render();return}const filter=event.target.closest?.('[data-open-key-filter]');if(filter){state.keyFilter=filter.dataset.openKeyFilter;state.view='keys';render()}});
function render(){app.className='';app.innerHTML=({home,shop,keys,finance,support,admin}[state.view]||home)();document.querySelectorAll('[data-view]').forEach(x=>x.onclick=async()=>{state.view=x.dataset.view;if(state.view==='admin'&&!state.admin)state.admin=await request('/api/admin/overview');if(state.view==='support')state.sessions=await request('/api/sessions').catch(()=>null);render()});document.querySelectorAll('[data-filter]').forEach(x=>x.onclick=()=>{state.keyFilter=x.dataset.filter;render()});document.querySelector('#keySearch')?.addEventListener('input',e=>{state.keyQuery=e.target.value;keysRefresh()});document.querySelector('#themeToggle')?.addEventListener('click',()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('theme',dark?'dark':'light')});document.querySelectorAll('.server-action').forEach(x=>x.onclick=async()=>{let reason;if(x.dataset.action==='unavailable'){reason=prompt('Причина отключения сервера');if(!reason)return}if(['archive','restore','available'].includes(x.dataset.action)&&!confirm('Подтвердить действие с сервером?'))return;try{const out=await request(`/api/admin/servers/${x.dataset.id}/action`,{method:'POST',body:JSON.stringify({action:x.dataset.action,reason})});toast(out.campaign_id?`Снимок #${out.campaign_id}: ${out.total} ключей`:'Сохранено');state.admin=await request('/api/admin/overview');render()}catch(e){toast(e.message)}});document.querySelector('#cleanupDays')?.addEventListener('change',async e=>{try{await request('/api/admin/servers/0/action',{method:'POST',body:JSON.stringify({action:'cleanup',days:Number(e.target.value)})});toast('Срок очистки сохранён');state.admin.cleanup.days=Number(e.target.value)}catch(e){toast(e.message)}});document.querySelectorAll('.rename-key').forEach(x=>x.onclick=async()=>{const label=prompt('Название устройства',x.dataset.label);if(label===null)return;try{await request(`/api/keys/${encodeURIComponent(x.dataset.key)}/label`,{method:'PATCH',body:JSON.stringify({label})});const key=state.me.keys.find(k=>k.name===x.dataset.key);if(key)key.device=label.trim();toast('Название сохранено');render()}catch(e){toast(e.message)}});document.querySelector('#logout')?.addEventListener('click',()=>request('/api/logout',{method:'POST'}).then(()=>location.reload()));document.querySelector('#revokeSessions')?.addEventListener('click',async()=>{if(!confirm('Завершить все остальные входы в кабинет?'))return;const out=await request('/api/sessions/revoke-others',{method:'POST'});state.sessions=await request('/api/sessions');toast(`Завершено сессий: ${out.revoked}`);render()});document.querySelector('#purchase')?.addEventListener('click',async()=>{const months=Number(document.querySelector('input[name=term]:checked')?.value),server_id=Number(document.querySelector('input[name=server]:checked')?.value);try{const x=await request('/api/purchases',{method:'POST',body:JSON.stringify({months,server_id})});document.querySelector('#purchaseResult').innerHTML=`<div class="success"><strong>Заявка #${x.payment_id} создана на ${money(x.amount_kopecks)}</strong><p>${esc(x.instructions)}</p><p class="muted">Оплатите и отправьте подтверждение в разделе «Финансы».</p></div>`}catch(e){toast(e.message)}});document.querySelector('#supportSend')?.addEventListener('click',async()=>{try{const x=await request('/api/support',{method:'POST',body:JSON.stringify({message:document.querySelector('#supportText').value})});toast(`Обращение #${x.ticket_id} отправлено`)}catch{toast('Не удалось отправить обращение')}});document.querySelector('#bindEmailSend')?.addEventListener('click',async()=>{const email=document.querySelector('#bindEmail').value;try{await request('/api/email/bind/request',{method:'POST',body:JSON.stringify({email})});document.querySelector('#bindConfirm').innerHTML='<input id="bindCode" inputmode="numeric" maxlength="6" placeholder="Код из письма"><button class="button" id="bindCodeSend">Подтвердить адрес</button>';document.querySelector('#bindCodeSend').onclick=async()=>{try{await request('/api/email/bind/confirm',{method:'POST',body:JSON.stringify({email,code:document.querySelector('#bindCode').value})});state.session.email=email;toast('Почта подтверждена');render()}catch(e){toast(e.message)}}}catch(e){toast(e.message)}});document.querySelector('#topup')?.addEventListener('click',async()=>{try{const x=await request('/api/payments/topup',{method:'POST',body:JSON.stringify({amount_rubles:Number(document.querySelector('#amount').value)})});document.querySelector('#proofBox').innerHTML=`<p class="muted">${esc(x.instructions)}</p><input id="proof" maxlength="500" placeholder="Номер операции"><button class="button" id="proofSend">Я оплатил</button>`;document.querySelector('#proofSend').onclick=async()=>{await request(`/api/payments/${x.payment_id}/proof`,{method:'POST',body:JSON.stringify({proof:document.querySelector('#proof').value})});toast('Подтверждение отправлено')}}catch(e){toast(e.message||'Проверьте сумму')}})}
function keysRefresh(){const q=document.querySelector('#keySearch')?.value||'';state.keyQuery=q;clearTimeout(keysRefresh.timer);keysRefresh.timer=setTimeout(render,180)}
const PWA_LOGIN_KEY='zpnet-pwa-login';
let pwaLoginTimer=null;
let volatilePwaLogin=null;
function pendingPwaLogin(){try{const value=JSON.parse(localStorage.getItem(PWA_LOGIN_KEY))||volatilePwaLogin;if(!value?.token||!value?.deep_link||value.expires_at<=Date.now()){localStorage.removeItem(PWA_LOGIN_KEY);volatilePwaLogin=null;return null}return value}catch{return volatilePwaLogin}}
function savePwaLogin(value){volatilePwaLogin=value;try{localStorage.setItem(PWA_LOGIN_KEY,JSON.stringify(value))}catch{}}
function clearPwaLogin(){volatilePwaLogin=null;try{localStorage.removeItem(PWA_LOGIN_KEY)}catch{}clearInterval(pwaLoginTimer);pwaLoginTimer=null}
async function pollPwaLogin(){const pending=pendingPwaLogin();if(!pending)return false;try{const out=await request('/api/telegram/login/poll',{method:'POST',body:JSON.stringify({token:pending.token})});if(out?.ok){clearPwaLogin();location.replace('/');return true}const status=document.querySelector('#pwaLoginStatus');if(status)status.textContent='Ожидаем подтверждение в Telegram…'}catch{clearPwaLogin();loginScreen();toast('Запрос входа устарел. Попробуйте ещё раз.')}return false}
function watchPwaLogin(){clearInterval(pwaLoginTimer);pollPwaLogin();pwaLoginTimer=setInterval(()=>{if(document.visibilityState==='visible')pollPwaLogin()},2000)}
async function beginPwaLogin(){const button=document.querySelector('#telegramPwaLogin');if(button){button.disabled=true;button.textContent='Создаём запрос…'}try{const out=await request('/api/telegram/login/request',{method:'POST'});savePwaLogin({token:out.token,deep_link:out.deep_link,expires_at:Date.now()+out.expires_in*1000});loginScreen();setTimeout(()=>{location.assign(out.deep_link)},150)}catch(e){if(button){button.disabled=false;button.textContent='Войти через Telegram'}toast(e.message||'Не удалось создать запрос входа')}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&pendingPwaLogin())pollPwaLogin()});
window.addEventListener('pageshow',()=>{if(pendingPwaLogin())pollPwaLogin()});
window.addEventListener('focus',()=>{if(pendingPwaLogin())pollPwaLogin()});
const EMAIL_LOGIN_KEY='zpnet-email-login';
let emailLoginTimer=null;
function pendingEmailLogin(){try{const value=JSON.parse(localStorage.getItem(EMAIL_LOGIN_KEY));if(!value?.email||value.expires_at<=Date.now()){localStorage.removeItem(EMAIL_LOGIN_KEY);return null}return value}catch{localStorage.removeItem(EMAIL_LOGIN_KEY);return null}}
function clearEmailLogin(){localStorage.removeItem(EMAIL_LOGIN_KEY);clearInterval(emailLoginTimer);emailLoginTimer=null}
function validLoginEmail(email){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)&&email.length<=254}
function maskEmail(email){const [name,domain]=email.split('@');return `${name.slice(0,2)}${name.length>2?'•••':''}@${domain}`}
async function sendEmailLogin(email){email=email.trim().toLowerCase();if(!validLoginEmail(email)){toast('Проверьте адрес электронной почты');document.querySelector('#loginEmail')?.focus();return}const button=document.querySelector('#loginEmailSend');if(button){button.disabled=true;button.textContent='Отправляем код…'}try{const out=await request('/api/email/login/request',{method:'POST',body:JSON.stringify({email})});localStorage.setItem(EMAIL_LOGIN_KEY,JSON.stringify({email,expires_at:Date.now()+(out.expires_in||600)*1000,retry_at:Date.now()+(out.retry_after||60)*1000}));loginScreen()}catch(e){if(button){button.disabled=false;button.textContent='Продолжить по почте'}toast(e.message||'Не удалось отправить код')}}
async function confirmEmailLogin(){const pending=pendingEmailLogin(),input=document.querySelector('#loginCode'),code=(input?.value||'').replace(/\D/g,'');if(!pending||code.length!==6){toast('Введите шестизначный код');input?.focus();return}const button=document.querySelector('#loginCodeSend');if(button){button.disabled=true;button.textContent='Проверяем…'}try{await request('/api/email/login/confirm',{method:'POST',body:JSON.stringify({email:pending.email,code})});clearEmailLogin();location.replace('/')}catch(e){if(button){button.disabled=false;button.textContent='Войти'}input?.select();document.querySelector('#emailLoginStatus').textContent='Код не подошёл или истёк. Проверьте письмо и попробуйте ещё раз.'}}
function updateEmailResend(){const pending=pendingEmailLogin(),button=document.querySelector('#resendEmailCode');if(!pending||!button)return;const seconds=Math.max(0,Math.ceil((pending.retry_at-Date.now())/1000));button.disabled=seconds>0;button.textContent=seconds>0?`Отправить повторно через ${seconds} с`:'Отправить код повторно'}
function bindEmailCodeScreen(){const input=document.querySelector('#loginCode');input?.focus();input?.addEventListener('input',()=>{input.value=input.value.replace(/\D/g,'').slice(0,6);if(input.value.length===6)confirmEmailLogin()});document.querySelector('#loginCodeSend').onclick=confirmEmailLogin;document.querySelector('#changeLoginEmail').onclick=()=>{clearEmailLogin();loginScreen()};document.querySelector('#resendEmailCode').onclick=()=>{const pending=pendingEmailLogin();if(pending)sendEmailLogin(pending.email)};updateEmailResend();clearInterval(emailLoginTimer);emailLoginTimer=setInterval(updateEmailResend,1000)}
function loginScreen(){const pwaPending=pendingPwaLogin(),emailPending=pendingEmailLogin(),telegram=state.catalog?.bot_username,emailEnabled=state.catalog?.email_login_enabled!==false;app.className='login';if(pwaPending){app.innerHTML=`<article class="card login-card"><div class="logo" style="margin:auto">◈</div><div class="eyebrow">Вход через Telegram</div><h1>Подтвердите вход</h1><p class="muted" id="pwaLoginStatus">Откройте Telegram и подтвердите вход. Затем вернитесь в приложение — кабинет откроется автоматически.</p><a class="button primary wide" id="openPwaTelegram" href="${esc(pwaPending.deep_link)}">Открыть Telegram</a><button class="button wide" id="pollPwaLogin">Я подтвердил — проверить</button><button class="text-button wide" id="cancelPwaLogin">Отменить</button><p class="login-note">Запрос одноразовый и действует 10 минут. Ссылка кабинета не открывается во внешнем браузере.</p></article>`;document.querySelector('#pollPwaLogin').onclick=pollPwaLogin;document.querySelector('#cancelPwaLogin').onclick=()=>{clearPwaLogin();loginScreen()};watchPwaLogin();return}clearInterval(pwaLoginTimer);if(emailEnabled&&emailPending){app.innerHTML=`<article class="card login-card email-login-card"><div class="logo" style="margin:auto">✉</div><div class="eyebrow">Вход по почте · шаг 2 из 2</div><h1>Введите код</h1><p class="muted">Отправили шестизначный код на <strong>${esc(maskEmail(emailPending.email))}</strong>. Проверьте также папку «Спам».</p><input class="email-code" id="loginCode" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]*" maxlength="6" aria-label="Шестизначный код" placeholder="000000"><p class="auth-status" id="emailLoginStatus" aria-live="polite">Код действует 10 минут и подходит только для одного входа.</p><button class="button primary wide" id="loginCodeSend">Войти</button><button class="button ghost wide" id="resendEmailCode">Отправить код повторно</button><button class="text-button wide" id="changeLoginEmail">Изменить адрес</button></article>`;bindEmailCodeScreen();return}clearInterval(emailLoginTimer);app.innerHTML=`<article class="card login-card"><div class="logo" style="margin:auto">◈</div><div class="eyebrow">Безопасный вход</div><h1>${esc(brand())}</h1><p class="muted">${emailEnabled?'Выберите удобный способ. Постоянный пароль не нужен.':'Подтвердите вход в Telegram и вернитесь в приложение.'}</p>${telegram?`<button class="button primary wide" id="telegramPwaLogin">Войти через Telegram</button>${emailEnabled?'<div class="login-divider"><span>или</span></div>':''}`:''}${emailEnabled?'<label class="auth-label" for="loginEmail">Электронная почта</label><input id="loginEmail" type="email" autocomplete="email" inputmode="email" autocapitalize="none" spellcheck="false" placeholder="name@example.ru"><button class="button wide" id="loginEmailSend">Продолжить по почте</button><p class="auth-status">Пришлём одноразовый код. Если это новый адрес, кабинет будет создан после подтверждения.</p>':'<p class="muted">Вход по почте пока не настроен администратором.</p>'}<button class="text-button wide" id="backPublic">← На главную</button></article>`;document.querySelector('#telegramPwaLogin')?.addEventListener('click',beginPwaLogin);document.querySelector('#backPublic').onclick=publicSiteV2;const emailInput=document.querySelector('#loginEmail');emailInput?.addEventListener('keydown',event=>{if(event.key==='Enter')sendEmailLogin(emailInput.value)});document.querySelector('#loginEmailSend')?.addEventListener('click',()=>sendEmailLogin(emailInput.value))}
