function publicSiteV2(){const c=state.catalog,telegram=c.bot_username?`https://t.me/${c.bot_username.replace(/^@/,'')}`:null,emailEnabled=c.email_login_enabled!==false,emailTrust=emailEnabled?'✓ Резервный вход по почте':'✓ Защищённый вход через бот',emailTitle=emailEnabled?'Доступ без Telegram':'Защищённый вход',emailText=emailEnabled?'Подтвердите адрес один раз и получайте одноразовый код входа на почту.':'Вход выполняется по одноразовой ссылке из Telegram-бота без постоянного пароля.',accessTitle=emailEnabled?'Кабинет доступен не только через Telegram':'Защищённый доступ к кабинету',accessText=emailEnabled?'Можно зарегистрироваться непосредственно по почте или войти по защищённой одноразовой ссылке из бота. Постоянные пароли сервис не хранит.':'Сейчас вход доступен по одноразовой ссылке из Telegram-бота. Вход по почте появится после настройки почтового шлюза.',accessEyebrow=emailEnabled?'Резервный доступ':'Доступ',faqAnswer=emailEnabled?'Регистрация и последующий вход в веб-кабинет работают по одноразовому коду из письма.':'Откройте одноразовую ссылку из Telegram-бота. После настройки почтового шлюза появится независимый вход по почте.';app.className='public';app.innerHTML=`<header class="public-nav"><a class="brand" href="/"><span class="logo">◈</span>${esc(brand())}</a><nav class="public-links"><a href="#benefits">Возможности</a><a href="#plans">Тарифы</a><a href="/instructions">Инструкции</a><a href="/status">Статус</a></nav><button class="button" id="openLogin">Личный кабинет</button></header><main><section class="public-hero"><div><div class="eyebrow">VPN без лишней сложности</div><h1>Привычный интернет<br><span>на всех устройствах</span></h1><p>Подключайте телефон, компьютер, планшет или роутер через AmneziaWG. Ключи, сроки, трафик, оплата и поддержка собраны в одном кабинете.</p><div class="actions"><button class="button primary" id="buyNow">Выбрать тариф</button><button class="button ghost" id="loginNow">Войти в кабинет</button></div><div class="trust-row"><span>✓ AWG 1.0</span><span>✓ QR-код и конфигурация</span><span>${emailTrust}</span></div></div><article class="card public-stat"><span class="badge">Личный кабинет</span><h2>Всё под вашим контролем</h2><div class="list-row"><span>Доступные локации</span><strong>${c.servers.length}</strong></div><div class="list-row"><span>Минимальный срок</span><strong>${c.tariffs[0]?.months||1} мес.</strong></div><div class="list-row"><span>Устройства</span><strong>телефон, ПК, роутер</strong></div><div class="list-row"><span>Поддержка</span><strong>в кабинете</strong></div></article></section><section id="benefits" class="public-section"><div class="eyebrow">Возможности</div><h2>Понятно с первого подключения</h2><div class="feature-grid"><article class="card"><span class="feature-icon">01</span><h3>Все устройства</h3><p class="muted">AmneziaWG на Android, iOS, Windows и macOS, а также совместимые роутеры Keenetic.</p></article><article class="card"><span class="feature-icon">02</span><h3>Прозрачное управление</h3><p class="muted">Смотрите статус, срок, трафик и последнее подключение. Скачивайте файл или открывайте QR-код.</p></article><article class="card"><span class="feature-icon">03</span><h3>${emailTitle}</h3><p class="muted">${emailText}</p></article></div></section><section id="plans" class="public-section plans-section"><div class="eyebrow">Тарифы</div><h2>Выберите удобный срок</h2><p class="muted section-copy">Стоимость берётся из актуальных настроек сервиса. После входа вы выберете сервер и способ оплаты.</p><div class="plan-grid">${c.tariffs.map((t,i)=>`<article class="card plan ${i===c.tariffs.length-1?'featured':''}"><span class="muted">${t.months} ${t.months===1?'месяц':'месяцев'}</span><div class="balance">${money(t.price_kopecks)}</div><p class="muted">AWG 1.0 · личный кабинет · поддержка</p><button class="button primary planBuy">Выбрать</button></article>`).join('')||'<article class="card empty">Тарифы скоро появятся</article>'}</div></section><section class="public-section access-section"><div><div class="eyebrow">${accessEyebrow}</div><h2>${accessTitle}</h2><p class="muted">${accessText}</p></div><button class="button primary" id="accessLogin">Войти</button></section><section id="faq" class="public-section faq"><div class="eyebrow">Частые вопросы</div><h2>Перед подключением</h2><details><summary>На каких устройствах работает VPN?</summary><p>На смартфонах, планшетах и компьютерах с приложением AmneziaWG. Также ключ можно установить на совместимый роутер Keenetic.</p></details><details><summary>Что будет, если Telegram недоступен?</summary><p>${faqAnswer}</p></details><details><summary>Где посмотреть срок и трафик?</summary><p>В разделе «Мои ключи» личного кабинета — отдельно для каждого подключения.</p></details></section><section class="public-cta"><div><h2>Готовы подключиться?</h2><p>Выберите тариф или откройте кабинет, если ключ уже есть.</p></div><div class="actions"><button class="button primary" id="ctaBuy">Выбрать тариф</button>${telegram?`<a class="button" href="${esc(telegram)}" rel="noopener">Открыть Telegram-бота</a>`:''}</div></section></main><footer><span>© ${esc(brand())}</span><span>VPN на базе AmneziaWG</span></footer>`;const login=()=>loginScreen();['openLogin','loginNow','accessLogin'].forEach(id=>document.querySelector(`#${id}`)?.addEventListener('click',login));['buyNow','ctaBuy'].forEach(id=>document.querySelector(`#${id}`)?.addEventListener('click',()=>document.querySelector('#plans').scrollIntoView({behavior:'smooth'})));document.querySelectorAll('.planBuy').forEach(x=>x.onclick=login)}
